BEGIN;
DO $$ DECLARE a uuid;s uuid;m uuid;c uuid;rule uuid;activity uuid;ev uuid;r jsonb;first_result jsonb;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('native-fast-owner@example.test','fixture','super_admin',true) RETURNING id INTO a;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash) VALUES(a,repeat('c1',32)) RETURNING id INTO s;
 INSERT INTO public.members(name,email) VALUES('Native Queue Fixture','native-queue@example.test') RETURNING id INTO m;
 INSERT INTO public.reward_credentials(member_id,kind,label,token_hash,encrypted_token) VALUES(m,'wallet','Wallet fixture',repeat('c2',32),'fixture') RETURNING id INTO c;
 INSERT INTO public.reward_rules(title,points) VALUES('Native check-in rule',10) RETURNING id INTO rule;
 INSERT INTO public.reward_activities(rule_id,title,points,opens_at,closes_at) VALUES(rule,'Native check-in activity',10,now()-interval '1 hour',now()+interval '1 hour') RETURNING id INTO activity;
 r:=public.native_checkin_targets(a,s);IF NOT r->'activities' @> jsonb_build_array(jsonb_build_object('id',activity)) THEN RAISE EXCEPTION 'Activity selection missing';END IF;
 first_result:=public.native_member_checkin(a,s,'activity',activity,NULL,repeat('c2',32),NULL,repeat('c3',32),repeat('c4',32),gen_random_uuid());
 IF first_result->>'status'<>'checked_in' OR first_result->>'points'<>'10' OR gdg_security.reward_balance(m)<>10 THEN RAISE EXCEPTION 'Direct activity scan failed';END IF;
 r:=public.native_member_checkin(a,s,'activity',activity,NULL,repeat('c2',32),NULL,repeat('c3',32),repeat('c4',32),gen_random_uuid());IF r<>first_result THEN RAISE EXCEPTION 'Interrupted response retry changed outcome';END IF;
 r:=public.native_member_checkin(a,s,'activity',activity,NULL,repeat('c2',32),NULL,repeat('c5',32),repeat('c4',32),gen_random_uuid());IF r->>'status'<>'duplicate' OR r->>'points'<>'0' OR gdg_security.reward_balance(m)<>10 THEN RAISE EXCEPTION 'Repeat scan awarded twice';END IF;
 BEGIN PERFORM public.native_member_checkin(a,s,'activity',activity,NULL,repeat('c2',32),NULL,repeat('c3',32),repeat('c6',32),gen_random_uuid());RAISE EXCEPTION 'Changed request accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CONFLICT' THEN RAISE;END IF;END;
 INSERT INTO public.events(title,description,start_at,location,slug,publication_status) VALUES('Native registered event','Fixture event',now(),'Test location','native-queue-event','published') RETURNING id INTO ev;
 r:=public.native_member_checkin(a,s,'event',ev,NULL,repeat('c2',32),NULL,repeat('c7',32),repeat('c4',32),gen_random_uuid());IF r->>'status'<>'not_registered' THEN RAISE EXCEPTION 'Unregistered person checked in';END IF;
 INSERT INTO public.event_attendance(event_id,attendee_name,attendee_email,idempotency_key,request_hash) VALUES(ev,'Native Queue Fixture','native-queue@example.test',repeat('c8',32),repeat('c9',32));
 r:=public.native_member_checkin(a,s,'event',ev,activity,repeat('c2',32),NULL,repeat('ca',32),repeat('c4',32),gen_random_uuid());
 IF r->>'status'<>'checked_in' OR NOT(SELECT attended FROM public.event_attendance WHERE event_id=ev AND attendee_email='native-queue@example.test') OR gdg_security.reward_balance(m)<>10 THEN RAISE EXCEPTION 'Event attendance or existing points failed';END IF;
 r:=public.native_member_checkin(a,s,'event',ev,NULL,repeat('c2',32),NULL,repeat('cb',32),repeat('c4',32),gen_random_uuid());IF r->>'status'<>'duplicate' THEN RAISE EXCEPTION 'Event duplicate not recognized';END IF;
 UPDATE public.reward_activities SET closes_at=now()-interval '1 minute',opens_at=now()-interval '1 hour' WHERE id=activity;
 BEGIN PERFORM public.native_member_checkin(a,s,'activity',activity,NULL,repeat('c2',32),NULL,repeat('cc',32),repeat('c4',32),gen_random_uuid());RAISE EXCEPTION 'Closed window accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 UPDATE public.reward_credentials SET revoked_at=now() WHERE id=c;
 BEGIN PERFORM public.native_member_checkin(a,s,'event',ev,NULL,repeat('c2',32),NULL,repeat('cd',32),repeat('c4',32),gen_random_uuid());RAISE EXCEPTION 'Revoked card accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 UPDATE public.admin_sessions SET revoked_at=now() WHERE id=s;
 BEGIN PERFORM public.native_checkin_targets(a,s);RAISE EXCEPTION 'Revoked session read targets';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_function_privilege('anon','public.native_checkin_targets(uuid,uuid)','EXECUTE') OR has_function_privilege('authenticated','public.native_member_checkin(uuid,uuid,text,uuid,uuid,text,text,text,text,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Native service functions exposed';END IF;
END $$;
ROLLBACK;
